<script setup lang="ts">
import {cmsDate} from '~/shared/cms/workflow.mjs'
definePageMeta({layout:'admin'})
const route=useRoute(),router=useRouter(),{api,message}=useCmsAdmin(),editing=ref<any>(null),baseline=ref(''),error=ref(''),notice=ref(''),busy=ref(false)
const tab=computed(()=>route.query.tab==='comments'?'comments':'inbox'),q=computed({get:()=>String(route.query.q||''),set:q=>setFilter({q})}),status=computed({get:()=>String(route.query.status||''),set:status=>setFilter({status})}),kind=computed({get:()=>String(route.query.kind||''),set:kind=>setFilter({kind})}),page=computed(()=>Math.max(1,Number(route.query.page)||1))
function setFilter(values:Record<string,string>){void router.replace({query:{...route.query,...values,page:undefined}})}
const {data:rows,refresh,error:loadError}=await useAsyncData<any[]>('cms-inbox',()=>api(tab.value),{watch:[tab]})
const statuses=computed(()=>tab.value==='inbox'?['待處理','處理中','已完成','垃圾訊息']:['待審核','已核准','已拒絕'])
const filtered=computed(()=>(rows.value||[]).filter(r=>(!status.value||r.status===status.value)&&(!kind.value||r.kind===kind.value)&&JSON.stringify(r).includes(q.value)))
const dirty=computed(()=>!!editing.value&&JSON.stringify(editing.value)!==baseline.value)
useCmsUnsaved(dirty)
watch(tab,()=>{editing.value=null})
function open(row:any){editing.value=JSON.parse(JSON.stringify(row));baseline.value=JSON.stringify(editing.value);error.value=''}
function close(){if(!busy.value&&(!dirty.value||window.confirm('還有未儲存的處理結果，確定關閉？')))editing.value=null}
function changeTab(value:string){void router.push({query:{tab:value}})}
async function save(){if(busy.value)return;busy.value=true;error.value='';try{await api(tab.value+'/'+editing.value.id,{method:'POST',body:{status:editing.value.status,note:editing.value.note||'',revision:editing.value.revision}});editing.value=null;notice.value='處理結果已儲存。';await refresh()}catch(e){error.value=message(e)}finally{busy.value=false}}
const names:Record<string,string>={name:'姓名',contactName:'聯絡人',phone:'電話',email:'電子郵件',company:'公司',note:'備註',comment:'留言',route:'留言頁面',experience:'經驗',budget:'預算',area:'地區',timeline:'預計時間',gender:'性別',age:'年齡',residence:'居住地',education:'學歷',occupation:'職業',lineId:'LINE ID',contactTimes:'方便聯繫時間',funding:'資金來源',storeType:'店面資訊',storeAddress:'店面地址',storeWidth:'店面寬（公尺）',storeArea:'實際坪數',team:'經營團隊',reasons:'選擇櫻花原因',concerns:'最在意的細節',motivation:'創業原因',sources:'得知加盟訊息',consent:'已同意資料使用',consentVersion:'同意說明版本',consentedAt:'同意時間'}
const details=computed(()=>Object.entries(editing.value?.body||{name:editing.value?.name,email:editing.value?.email,comment:editing.value?.comment,route:editing.value?.route}).map(([key,value])=>({label:names[key]||'其他填寫內容',value:Array.isArray(value)?value.join('、'):typeof value==='boolean'?(value?'是':'否'):value})))

</script>
<template><div class="cms-page"><div class="cms-heading"><h1>申請與留言</h1><button class="cms-button" @click="refresh()">重新整理</button></div><p v-if="loadError" class="cms-error" role="alert">{{ message(loadError) }}</p><p v-if="notice" class="cms-notice" role="status">{{ notice }}</p><nav class="cms-tabs" aria-label="申請或留言"><button :class="{active:tab==='inbox'}" @click="changeTab('inbox')">加盟與建案申請</button><button :class="{active:tab==='comments'}" @click="changeTab('comments')">網站留言</button></nav><div class="cms-content-tools"><label class="cms-search"><input v-model="q" aria-label="搜尋申請與留言" placeholder="搜尋姓名、電話或內容" /></label><select v-if="tab==='inbox'" v-model="kind" aria-label="申請種類"><option value="">全部申請</option><option value="franchise">加盟申請</option><option value="builder">建案預約</option></select><select v-model="status" aria-label="處理狀態篩選"><option value="">全部狀態</option><option v-for="s in statuses" :key="s">{{ s }}</option></select></div><div class="cms-panel"><button v-for="r in filtered.slice((page-1)*20,page*20)" :key="r.id" class="cms-resource-row" @click="open(r)"><div><strong>{{ r.name||r.body?.name||r.body?.contactName }}</strong><small>{{ r.kind==='franchise'?'加盟申請':r.kind==='builder'?'建案預約':'網站留言' }} · {{ cmsDate(r.createdAt) }}</small></div><span class="cms-status">{{ r.status }} →</span></button><p v-if="!filtered.length" class="cms-empty">沒有符合的紀錄</p></div><div v-if="filtered.length>20" class="cms-actions cms-pagination"><NuxtLink v-if="page>1" class="cms-button" :to="{query:{...route.query,page:page-1}}">上一頁</NuxtLink><span>{{ page }} / {{ Math.ceil(filtered.length/20) }}</span><NuxtLink v-if="page*20<filtered.length" class="cms-button" :to="{query:{...route.query,page:page+1}}">下一頁</NuxtLink></div><AdminDialog :open="!!editing" :title="tab==='inbox'?'處理申請':'處理網站留言'" @close="close"><form v-if="editing" class="cms-form" @submit.prevent="save"><dl class="cms-inbox-detail"><template v-for="(item,i) in details" :key="i"><dt>{{ item.label }}</dt><dd>{{ item.value||'未填寫' }}</dd></template></dl><label>處理狀態<select v-model="editing.status"><option v-for="s in statuses" :key="s">{{ s }}</option></select></label><p v-if="tab==='comments'" class="cms-field-help">核准後，官網只會顯示姓名、留言與日期，不會顯示電子郵件。</p><label v-if="tab==='inbox'">內部備註<textarea v-model="editing.note" rows="4" placeholder="記下聯繫結果或後續工作" /></label><p v-if="error" class="cms-error" role="alert">{{ error }}</p><div class="cms-dialog-actions"><button type="button" class="cms-button" :disabled="busy" @click="close">返回列表</button><button class="cms-button cms-button-gold" :disabled="busy">{{ busy?'儲存中…':'儲存處理結果' }}</button></div></form></AdminDialog></div></template>
